/**
 * Implementation of the version block. See ToolVersion.h for what it is for.
 *
 * @author Copyright (c) 2026
 */

#include "ToolVersion.h"

// Generated by make (tools/make_version_stamp.sh). Included here rather than passed as -D on the
// command line so the value lives in exactly one place, and so this file can be compiled on its
// own - a quick `g++ -c` does not have configure's DEFS.
#include "version_stamp.h"

#include <ostream>
#include <string>

// configure defines this for every target in the Makefile; the fallback is for that standalone
// compile, where there is no VERSION to be had either.
#ifndef VERSION
#define VERSION "unknown"
#endif

#ifndef TOOL_VERSION_COMMIT
#error "version_stamp.h is missing TOOL_VERSION_COMMIT - was it generated by tools/make_version_stamp.sh?"
#endif

namespace ToolVersion {

const char * const URL =
	"https://github.com/majorkingleo/bf1942-adjust-monitor-settings";

const char * const AUTHOR = "Martin Oberzalek";

bool is_version_switch( const std::string & token )
{
	if( token == "-v" || token == "-V" ) {
		return true;
	}

	std::string lowered = token;

	for( char & c : lowered ) {
		if( c >= 'A' && c <= 'Z' ) {
			c = static_cast<char>( c - 'A' + 'a' );
		}
	}

	return lowered == "--version";
}

bool requested( const std::vector<std::string> & args )
{
	for( const std::string & token : args ) {
		if( is_version_switch( token ) ) {
			return true;
		}
	}

	return false;
}

std::string text( const char * program )
{
	std::string out;

	out += program;
	out += " ";
	out += VERSION;
	out += "\n";

	out += "  commit   ";
	out += TOOL_VERSION_COMMIT;
	out += " (";
	out += TOOL_VERSION_DATE;
	out += ")\n";

	out += "  repo     ";
	out += URL;
	out += "\n";

	out += "  author   ";
	out += AUTHOR;
	out += "\n";

	return out;
}

void print( std::ostream & out, const char * program )
{
	out << text( program );
}

} // namespace ToolVersion
